<?php
declare(strict_types=1);
namespace Sentinel\Tests\Integration;
use PHPUnit\Framework\TestCase;
use Sentinel\Core\HttpException;
use Sentinel\Services\FieldOperationsService;
use Sentinel\Tests\FieldFixture;
final class ServiceDeliveryTest extends TestCase
{
 private function fixture():array {[$app,$db,$ctx]=FieldFixture::create();$db->execute('INSERT INTO user_roles VALUES(2,1,101)');$db->execute('INSERT INTO client_portal_access VALUES(101,2,1)');return [$app,$db,$ctx];}
 private function rejects(callable $fn,int $status):void {try{$fn();self::fail('Expected rejection');}catch(HttpException $e){self::assertSame($status,$e->statusCode(),$e->getMessage());}}
 private function incident($db):void {$db->execute("INSERT INTO incidents(incident_uuid,company_id,site_id,incident_number,incident_type,incident_category,description,occurred_at) VALUES(:uuid,101,1,'ALARM-1','ALARM','SECURITY','Alarm at gate',:now)",['uuid'=>uuid4(),'now'=>gmdate('Y-m-d H:i:s')]);}
 public function testAlarmUsesDispatchAndOnlyAssignedResponderCanRecordArrival():void {[$app,$db,$ctx]=$this->fixture();$this->incident($db);$s=$app->container()->make('response_transport_service');$id=$s->createAlarm(['incident_id'=>1,'source_reference'=>'PANEL-1','received_at'=>gmdate('Y-m-d H:i:s',time()-60)])['id'];$s->alarmAction($id,'dispatch',['expected_revision'=>1,'responder_user_id'=>2,'response_due_at'=>gmdate('Y-m-d H:i:s',time()+600)]);$this->rejects(fn()=>$s->respond($id,'accept',['expected_revision'=>1]),404);$ctx->setUser('2');self::assertSame('ACCEPTED',$s->respond($id,'accept',['expected_revision'=>1])['state']);self::assertSame('ARRIVED',$s->respond($id,'arrive',['expected_revision'=>2])['state']);$ctx->setUser('1');$this->rejects(fn()=>$s->alarmAction($id,'close',['expected_revision'=>2,'outcome'=>'FALSE_ALARM','notes'=>'No intrusion']),422);self::assertTrue($s->alarmAction($id,'close',['expected_revision'=>2,'outcome'=>'FALSE_ALARM','false_alarm_cause'=>'Loose sensor','notes'=>'Sensor checked'])['closed']);self::assertSame('CLOSED',$db->fetch('SELECT state FROM dispatch_jobs')['state']);self::assertSame('Loose sensor',$s->alarms(['site_id'=>1])[0]['false_alarm_cause']);self::assertGreaterThanOrEqual(60,$s->alarms(['site_id'=>1])[0]['response_seconds']);}
 public function testTransportCapacityOwnManifestAndDropoffGate():void {[$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('response_transport_service');$departure=gmdate('Y-m-d H:i:s',time()+3600);$id=$s->createRun(['site_id'=>1,'route_name'=>'North route','vehicle_registration'=>'TEST123','capacity'=>1,'driver_user_id'=>1,'departs_at'=>$departure,'pickup_grace_minutes'=>5,'notes'=>'Company vehicle'])['id'];$passenger=$s->passenger($id,['employee_id'=>2,'pickup_point'=>'Station','pickup_at'=>$departure])['id'];$this->rejects(fn()=>$s->passenger($id,['employee_id'=>1,'pickup_point'=>'Gate','pickup_at'=>$departure]),409);$ctx->setUser('2');self::assertCount(1,$s->transport([],true)[0]['passengers']);$ctx->setUser('1');$db->execute('UPDATE guard_transport_runs SET departs_at=:at',['at'=>gmdate('Y-m-d H:i:s',time()-60)]);$s->transportAction($id,'start',['expected_revision'=>1,'notes'=>'Driver started']);$s->transportAction($id,'board',['expected_revision'=>2,'passenger_id'=>$passenger,'notes'=>'Guard boarded']);$this->rejects(fn()=>$s->transportAction($id,'finish',['expected_revision'=>3,'notes'=>'Attempt early finish']),409);$s->transportAction($id,'alight',['expected_revision'=>3,'passenger_id'=>$passenger,'notes'=>'Guard dropped at site']);self::assertSame('COMPLETED',$s->transportAction($id,'finish',['expected_revision'=>4,'notes'=>'All passengers accounted for'])['state']);}
 private function risk():array {return ['site_id'=>1,'expected_revision'=>0,'title'=>'Gate risk assessment','effective_on'=>gmdate('Y-m-d'),'review_on'=>gmdate('Y-m-d',time()+86400*30),'hazards'=>[['hazard'=>'Vehicle approach','likelihood'=>4,'impact'=>4,'controls'=>['Keep pedestrian lane separate'],'owner_user_id'=>1]]];}
 public function testRiskRatingsClientFingerprintAndReassignmentPrivacy():void {[$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('site_delivery_plan_service');$id=$s->publish('RISK',$this->risk())['id'];$ctx->setUser('2');$r=$s->list('RISK',['site_id'=>1],'CLIENT')[0];self::assertSame(16,$r['content']['hazards'][0]['score']);self::assertSame('HIGH',$r['content']['hazards'][0]['rating']);self::assertTrue($s->acknowledge($id,['expected_hash'=>$r['content_hash']],'CLIENT')['acknowledged']);$ctx->setUser('1');$s->publish('RISK',[...$this->risk(),'expected_revision'=>1,'title'=>'Revised gate assessment']);$ctx->setUser('2');$this->rejects(fn()=>$s->acknowledge($id,['expected_hash'=>$r['content_hash']],'CLIENT'),409);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$this->rejects(fn()=>$s->list('RISK',['site_id'=>1],'CLIENT'),404);}
 public function testPostOrdersRequireDutyAndContinuityRequiresEveryRecordedStep():void {[$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('site_delivery_plan_service');$base=['site_id'=>1,'expected_revision'=>0,'title'=>'Post orders','effective_on'=>gmdate('Y-m-d'),'review_on'=>gmdate('Y-m-d',time()+86400*30)];$id=$s->publish('POST_ORDERS',$base+['duties'=>['Check gate identity'],'contacts'=>'Control room radio 1'])['id'];$ctx->setUser('2');$this->rejects(fn()=>$s->list('POST_ORDERS',['site_id'=>1],'SELF'),404);$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_end_at,assignment_status) VALUES(1,101,2,1,:end,'ASSIGNED')",['end'=>gmdate('Y-m-d H:i:s',time()+86400)]);$r=$s->list('POST_ORDERS',['site_id'=>1],'SELF')[0];self::assertTrue($s->acknowledge($id,['expected_hash'=>$r['content_hash']],'SELF')['acknowledged']);$ctx->setUser('1');$plan=$s->publish('CONTINUITY',$base+['scenarios'=>[['type'=>'NETWORK','steps'=>['Use paper register','Notify control'],'fallback_contact'=>'Radio channel 1']]])['id'];$run=$s->activate($plan,['scenario_index'=>0,'reason'=>'Network outage'])['id'];$this->rejects(fn()=>$s->activationAction($run,'close',['expected_revision'=>1,'notes'=>'Not yet done']),409);$s->activationAction($run,'step',['expected_revision'=>1,'step_number'=>1,'notes'=>'Paper log in use']);$s->activationAction($run,'step',['expected_revision'=>2,'step_number'=>2,'notes'=>'Control notified']);self::assertSame('CLOSED',$s->activationAction($run,'close',['expected_revision'=>3,'notes'=>'Connection restored; paper records reconciled'])['state']);}
 public function testEquipmentFailureCreatesOneDefectAndBlocksFalsePass():void {[$app,$db,$ctx]=$this->fixture();$db->execute("INSERT INTO equipment_items VALUES(1,101,'RADIO-1','Radio')");$s=$app->container()->make('operational_oversight_service');$id=$s->schedule(['site_id'=>1,'equipment_id'=>1,'checklist'=>['Battery charges','Test call works'],'interval_days'=>7,'assignee_user_id'=>1,'next_due_at'=>gmdate('Y-m-d H:i:s')])['id'];$in=['expected_revision'=>1,'operation_uuid'=>uuid4(),'checks'=>[true,false],'notes'=>'Test call failed'];$r=$s->inspect($id,$in);self::assertNotNull($r['maintenance_ticket_id']);self::assertSame($r['id'],$s->inspect($id,$in)['id']);self::assertSame(1,(int)$db->fetch('SELECT COUNT(*) AS n FROM maintenance_tickets')['n']);$this->rejects(fn()=>$s->inspect($id,['expected_revision'=>2,'operation_uuid'=>uuid4(),'checks'=>[true,true],'notes'=>'Try passing without repair']),409);$db->execute("UPDATE maintenance_tickets SET state='VERIFIED'");self::assertTrue($s->inspect($id,['expected_revision'=>2,'operation_uuid'=>uuid4(),'checks'=>[true,true],'notes'=>'Workshop repair verified and test call passed'])['passed']);}
 public function testHandoverFreezesSnapshotAndRequiresIncomingAcceptance():void {[$app,$db,$ctx]=$this->fixture();$this->incident($db);$s=$app->container()->make('operational_oversight_service');$id=$s->handover(['site_id'=>1,'incoming_user_id'=>2,'notes'=>'Monitor open gate alarm'])['id'];$r=$s->handovers(['site_id'=>1])['handovers'][0];self::assertCount(1,$r['snapshot']['unresolved_incidents']);$this->rejects(fn()=>$s->acceptHandover($id,['expected_revision'=>1,'expected_hash'=>$r['snapshot_hash'],'notes'=>'Outgoing self acceptance']),403);$ctx->setUser('2');$this->rejects(fn()=>$s->acceptHandover($id,['expected_revision'=>1,'expected_hash'=>'wrong','notes'=>'Unknown snapshot']),409);self::assertTrue($s->acceptHandover($id,['expected_revision'=>1,'expected_hash'=>$r['snapshot_hash'],'notes'=>'Incoming supervisor read the snapshot'])['accepted']);}
 private function contractor():array {return ['company_name'=>'Partner Security','registration_reference'=>'REG1','contact_details'=>'Operations desk','licence_reference'=>'LIC1','licence_expires_on'=>gmdate('Y-m-d',time()+60*86400),'insurance_reference'=>'POL1','insurance_expires_on'=>gmdate('Y-m-d',time()+30*86400),'state'=>'ACTIVE'];}
 public function testContractorExpiryApprovedSitesAndRoleMarkerAreEnforcedImmediately():void {[$app,$db,$ctx]=FieldFixture::create();$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(2,9001,101)');$db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(101,2,1,1,:now)',['now'=>gmdate('Y-m-d H:i:s')]);$s=$app->container()->make('subcontractor_service');$id=$s->save(null,$this->contractor())['id'];$s->member($id,['user_id'=>2,'enabled'=>true]);$policy=$app->container()->make('subcontractor_policy');self::assertTrue($policy->allowed('2'));self::assertFalse($policy->allowed('2',1));$s->approveSite($id,['expected_revision'=>1,'site_id'=>1,'valid_until'=>gmdate('Y-m-d',time()+10*86400)]);self::assertTrue($policy->allowed('2',1));self::assertFalse($policy->allowed('2',2));$s->revokeSite($id,['site_id'=>1,'notes'=>'Client withdrew approval']);self::assertFalse($policy->allowed('2',1));$s->approveSite($id,['expected_revision'=>1,'site_id'=>1,'valid_until'=>gmdate('Y-m-d',time()+10*86400)]);$s->save($id,[...$this->contractor(),'expected_revision'=>1]);self::assertFalse($policy->allowed('2',1));$s->approveSite($id,['expected_revision'=>2,'site_id'=>1,'valid_until'=>gmdate('Y-m-d',time()+10*86400)]);$db->execute("UPDATE subcontractor_companies SET insurance_expires_on='2020-01-01'");self::assertFalse($policy->allowed('2'));self::assertFalse($app->container()->make('authorization_service')->isAllowed('2','guard.self'));$this->rejects(fn()=>$s->member($id,['user_id'=>1,'enabled'=>false]),422);}
 public function testExtraGuardRequestQuotesAndWholePeriodCoverage():void {[$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('client_delivery_service');$start=gmdate('Y-m-d H:i:s',time()+3600);$end=gmdate('Y-m-d H:i:s',time()+7200);$ctx->setUser('2');$id=$s->create(['site_id'=>1,'request_type'=>'EVENT','title'=>'Evening event','details'=>'One extra guard','starts_at'=>$start,'ends_at'=>$end,'required_guards'=>1],true)['id'];$ctx->setUser('1');$s->quote($id,['expected_revision'=>1,'currency'=>'ZAR','unit_minor'=>50000,'tax_basis_points'=>0,'terms'=>'One-off price per guard for the whole period','valid_until'=>gmdate('Y-m-d')]);$r=$s->list(['site_id'=>1])[0];$ctx->setUser('2');$s->action($id,'accept',['expected_revision'=>2,'expected_hash'=>$r['quotation']['shared_hash'],'notes'=>'Accepted'],true);$ctx->setUser('1');$db->execute("INSERT INTO shift_assignments(shift_assignment_id,company_id,employee_id,site_id,shift_start_at,shift_end_at,assignment_status) VALUES(1,101,2,1,:start,:end,'ASSIGNED')",compact('start','end'));self::assertSame('SCHEDULED',$s->action($id,'schedule',['expected_revision'=>3,'shift_ids'=>[1],'notes'=>'Guard booked'])['state']);$this->rejects(fn()=>$s->action($id,'complete',['expected_revision'=>4,'notes'=>'Before event ends']),409);$db->execute("UPDATE shift_assignments SET assignment_status='CANCELLED'");$db->execute('UPDATE extra_service_requests SET ends_at=:end',['end'=>gmdate('Y-m-d H:i:s',time()-1)]);$this->rejects(fn()=>$s->action($id,'complete',['expected_revision'=>4,'notes'=>'Stale coverage']),409);}
 public function testAnalyticsUsesCurrentApprovalsAndLabelsUnknownArrivals():void {[$app,$db]=$this->fixture();$date=gmdate('Y-m-d');$db->execute('INSERT INTO attendance VALUES(1,101,2,1,:date,:start,:end,NULL,NULL)',['date'=>$date,'start'=>$date.' 00:00:00','end'=>$date.' 02:00:00']);$row=$db->fetch('SELECT attendance_id,employee_id,site_id,shift_date,clock_in_at,clock_out_at FROM attendance');$db->execute('INSERT INTO attendance_approvals VALUES(101,1,1,:now,:hash)',['now'=>gmdate('Y-m-d H:i:s'),'hash'=>FieldOperationsService::attendanceHash($row)]);$s=$app->container()->make('operational_oversight_service');$data=$s->analytics(['date_from'=>$date,'date_to'=>$date,'weekly_threshold_minutes'=>60]);self::assertSame(7200,$data['sites'][0]['approved_work_seconds']);self::assertSame(3600,$data['sites'][0]['estimated_overtime_seconds']);self::assertNull($data['sites'][0]['mean_dispatch_to_arrival_seconds']);$db->execute('UPDATE attendance SET clock_out_at=:end',['end'=>$date.' 03:00:00']);self::assertSame(0,$s->analytics(['date_from'=>$date,'date_to'=>$date])['sites'][0]['approved_work_seconds']);}
 public function testClientMobilisationApprovalGatesLegacyActivationToo():void {[$app,$db,$ctx]=$this->fixture();foreach(['contract_id INTEGER','status TEXT','updated_by_user_id INTEGER']as$c)$db->execute('ALTER TABLE sites ADD COLUMN '.$c);$db->execute("UPDATE sites SET status='ONBOARDING',contract_id=1 WHERE site_id=1");$db->execute('CREATE TABLE contracts(contract_id INTEGER PRIMARY KEY,company_id INTEGER,client_id INTEGER,status TEXT,deleted_at TEXT,updated_by_user_id INTEGER)');$db->execute("INSERT INTO contracts VALUES(1,101,1,'DRAFT',NULL,1)");$db->execute("INSERT INTO site_onboardings(company_id,quotation_id,contract_id,site_id,conversion_hash,created_by_user_id,created_at) VALUES(101,1,1,1,'hash',1,:now)",['now'=>gmdate('Y-m-d H:i:s')]);for($i=0;$i<7;$i++)$db->execute('INSERT INTO mobilisation_tasks(company_id,onboarding_id,task_name,completed_at,evidence_reference) VALUES(101,1,:name,:now,:ref)',['name'=>'Check '.$i,'now'=>gmdate('Y-m-d H:i:s'),'ref'=>'Evidence '.$i]);$s=$app->container()->make('client_delivery_service');$review=$s->prepare('1',['expected_revision'=>0,'contacts'=>[['name'=>'Duty manager','role'=>'Emergency','phone'=>'+27 example']],'survey_reference'=>'Survey reviewed 1'])['id'];$this->rejects(fn()=>$app->container()->make('quotation_service')->activate('1'),409);$r=$s->onboardings(['site_id'=>1])[0]['review'];$ctx->setUser('2');self::assertSame('ACCEPTED',$s->decidePacket($review,'accept',['expected_hash'=>$r['packet_hash'],'notes'=>'Readiness reviewed'])['state']);$ctx->setUser('1');$db->execute('UPDATE contracts SET updated_by_user_id=2');$this->rejects(fn()=>$app->container()->make('quotation_service')->activate('1'),409);$db->execute('UPDATE contracts SET updated_by_user_id=1');self::assertTrue($s->activate('1')['activated']);}
 public function testContractorSelfCustodyAndFleetCannotBypassSiteApproval():void {[$app,$db,$ctx]=FieldFixture::create();$db->execute("INSERT INTO permissions VALUES(9001,101,'site_scope.restricted','ACTIVE')");$db->execute('INSERT INTO role_permissions VALUES(2,9001,101)');$db->execute('INSERT INTO user_site_grants(company_id,user_id,site_id,granted_by_user_id,granted_at) VALUES(101,2,1,1,:now)',['now'=>gmdate('Y-m-d H:i:s')]);$contractors=$app->container()->make('subcontractor_service');$id=$contractors->save(null,$this->contractor())['id'];$contractors->member($id,['user_id'=>2,'enabled'=>true]);$keys=$app->container()->make('key_custody_service');$key=$keys->create(['site_id'=>1,'asset_code'=>'K1','asset_name'=>'Gate key','asset_type'=>'KEY'])['id'];$loan=$keys->issue($key,['expected_revision'=>1,'employee_id'=>2,'due_at'=>gmdate('Y-m-d H:i:s',time()+3600),'notes'=>'Physical issue reserved'])['id'];$fleet=$app->container()->make('fleet_operations_service');$vehicle=$fleet->create(['site_id'=>1,'registration'=>'TEST1','description'=>'Patrol car','odometer_km'=>0,'next_service_km'=>1000,'next_service_on'=>gmdate('Y-m-d',time()+30*86400)])['id'];$trip=$fleet->allocate($vehicle,['employee_id'=>2,'starts_at'=>gmdate('Y-m-d H:i:s',time()-60),'ends_at'=>gmdate('Y-m-d H:i:s',time()+3600),'purpose'=>'Patrol'])['id'];$ctx->setUser('2');self::assertSame([],$keys->mine());self::assertSame([],$fleet->list([],true));$this->rejects(fn()=>$keys->selfAction($loan,'accept',['expected_revision'=>1,'notes'=>'Unapproved','signature_base64'=>'invalid']),404);$this->rejects(fn()=>$fleet->tripAction($trip,'cancel',['expected_revision'=>1,'odometer_km'=>0],true),404);$ctx->setUser('1');$contractors->approveSite($id,['expected_revision'=>1,'site_id'=>1,'valid_until'=>gmdate('Y-m-d',time()+86400)]);$ctx->setUser('2');self::assertCount(1,$keys->mine());self::assertCount(1,$fleet->list([],true));}
 public function testInspectionHandoverAndAuditFailureKeepDefectsConsistent():void {[$app,$db,$ctx]=$this->fixture();$db->execute("INSERT INTO equipment_items VALUES(1,101,'TORCH1','Torch')");$s=$app->container()->make('operational_oversight_service');$id=$s->schedule(['site_id'=>1,'equipment_id'=>1,'checklist'=>['Light works'],'interval_days'=>7,'assignee_user_id'=>1,'next_due_at'=>gmdate('Y-m-d H:i:s')])['id'];$s->reschedule($id,['expected_revision'=>1,'assignee_user_id'=>2,'next_due_at'=>gmdate('Y-m-d H:i:s'),'interval_days'=>7,'active'=>true,'notes'=>'Cover absent inspector']);$this->rejects(fn()=>$s->inspect($id,['expected_revision'=>2,'operation_uuid'=>uuid4(),'checks'=>[false],'notes'=>'Former inspector']),403);$ctx->setUser('2');$db->execute("CREATE TRIGGER reject_delivery_audit BEFORE INSERT ON audit_logs BEGIN SELECT RAISE(FAIL,'audit unavailable'); END");try{$s->inspect($id,['expected_revision'=>2,'operation_uuid'=>uuid4(),'checks'=>[false],'notes'=>'Failed light']);self::fail('Audit failure required');}catch(\PDOException){}self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM maintenance_tickets')['n']);self::assertSame(0,(int)$db->fetch('SELECT COUNT(*) AS n FROM equipment_check_results')['n']);self::assertSame(2,(int)$db->fetch('SELECT revision FROM equipment_check_schedules')['revision']);}
 public function testPickupAndPlanReviewRemindersResolveWithoutRepeatedNotifications():void {[$app,$db,$ctx]=$this->fixture();$db->execute('CREATE TABLE contracts(contract_id INTEGER,company_id INTEGER,end_date TEXT,status TEXT,deleted_at TEXT)');$app->container()->make('pilot_setup_service')->settings(['reminder_user_id'=>1,'expected_revision'=>0]);$s=$app->container()->make('response_transport_service');$at=gmdate('Y-m-d H:i:s',time()+3600);$run=$s->createRun(['site_id'=>1,'route_name'=>'Pickup','vehicle_registration'=>'TEST','capacity'=>1,'driver_user_id'=>1,'departs_at'=>$at,'pickup_grace_minutes'=>5,'notes'=>'Transport'])['id'];$passenger=$s->passenger($run,['employee_id'=>2,'pickup_point'=>'Station','pickup_at'=>$at])['id'];$db->execute("UPDATE guard_transport_runs SET state='IN_PROGRESS',departs_at=:at",['at'=>gmdate('Y-m-d H:i:s',time()-3600)]);$db->execute('UPDATE guard_transport_passengers SET pickup_at=:at',['at'=>gmdate('Y-m-d H:i:s',time()-1800)]);$worker=$app->container()->make('business_reminder_service');self::assertSame(1,$worker->tick()['reminders']);self::assertSame(0,$worker->tick()['reminders']);$s->transportAction($run,'missed',['expected_revision'=>1,'passenger_id'=>$passenger,'notes'=>'Driver contacted guard; alternative arranged']);$worker->tick();self::assertSame('RESOLVED',$worker->list()[0]['state']);}
 public function testLegacyQuotationDecisionSynchronizesExtraServiceAndStopsMonthlyConversion():void {[$app,$db,$ctx]=$this->fixture();$s=$app->container()->make('client_delivery_service');$id=$s->create(['site_id'=>1,'request_type'=>'EXTRA_GUARDS','title'=>'Extra gate cover','details'=>'Requested coverage','starts_at'=>gmdate('Y-m-d H:i:s',time()+3600),'ends_at'=>gmdate('Y-m-d H:i:s',time()+7200),'required_guards'=>1])['id'];$s->quote($id,['expected_revision'=>1,'currency'=>'ZAR','unit_minor'=>10000,'tax_basis_points'=>0,'terms'=>'One-off','valid_until'=>gmdate('Y-m-d')]);$q=$s->list(['site_id'=>1])[0]['quotation'];$ctx->setUser('2');$quotes=$app->container()->make('quotation_service');$quotes->decide((string)$q['quotation_id'],'accept',['expected_hash'=>$q['shared_hash'],'notes'=>'Accepted in quotation portal']);self::assertSame('ACCEPTED',$s->list(['site_id'=>1],true)[0]['state']);$ctx->setUser('1');$this->rejects(fn()=>$quotes->convert((string)$q['quotation_id'],[]),409);$db->execute('UPDATE sites SET client_id=2 WHERE site_id=1');$ctx->setUser('2');$this->rejects(fn()=>$quotes->detail((string)$q['quotation_id'],true),404);self::assertSame([],$quotes->list(true));}
}
